NPObject *jeti_string_from_cstr(const char *cstr) {
    if (!cstr) cstr = "";
    NPObject *obj = jeti_alloc(&jeti_NPString_class);
    if (!obj) return NULL;
    struct NPString *str = (struct NPString *)obj;
    size_t len = strlen(cstr);
    str->_cstr = (char *)malloc(len + 1);
    if (str->_cstr) strcpy(str->_cstr, cstr);
    str->_length = len;
    str->_hash = 0;
    str->_hashIsValid = 0;
    return jeti_autorelease(obj);
}

